"use client";

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { Menu, X } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * AppBar — a web application top bar: a brand slot, a row of primary nav
 * links, and a trailing actions slot inside a sticky bordered header. Below
 * the `md` breakpoint the nav collapses behind a menu toggle into a panel
 * under the bar.
 *
 * <AppBar>
 *   <AppBarBrand>Acme</AppBarBrand>
 *   <AppBarNav>
 *     <AppBarLink href="/" active>Overview</AppBarLink>
 *     <AppBarLink href="/reports">Reports</AppBarLink>
 *   </AppBarNav>
 *   <AppBarActions><Button size="sm">New</Button></AppBarActions>
 * </AppBar>
 *
 * `NavigationBar` is the mobile back-button bar; this is the desktop app shell.
 */

interface AppBarCtx {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
}
const Ctx = React.createContext<AppBarCtx | null>(null);
const useAppBar = () => {
  const ctx = React.useContext(Ctx);
  if (!ctx) throw new Error("AppBar parts must be used within <AppBar>");
  return ctx;
};

const AppBar = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  ({ className, children, ...props }, ref) => {
    const [open, setOpen] = React.useState(false);

    const nav = React.Children.toArray(children).find(
      (c): c is React.ReactElement<React.ComponentProps<typeof AppBarNav>> =>
        React.isValidElement(c) && c.type === AppBarNav,
    );

    return (
      <Ctx.Provider value={{ open, setOpen }}>
        <header
          ref={ref}
          className={cn(
            "sticky top-0 z-sticky w-full border-b border-border bg-background/95 font-sans",
            "backdrop-blur supports-[backdrop-filter]:bg-background/75",
            className,
          )}
          {...props}
        >
          <div className="mx-auto flex h-14 max-w-screen-2xl items-center gap-4 px-4">
            {children}
            {nav && (
              <button
                type="button"
                aria-label={open ? "Close menu" : "Open menu"}
                aria-expanded={open}
                onClick={() => setOpen((o) => !o)}
                className={cn(
                  "ms-auto inline-flex size-9 items-center justify-center rounded-md text-foreground outline-none transition-colors md:hidden",
                  "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
                )}
              >
                {open ? <X className="size-5" /> : <Menu className="size-5" />}
              </button>
            )}
          </div>
          {nav && open && (
            <nav className="flex flex-col gap-1 border-t border-border p-2 md:hidden">
              {nav.props.children}
            </nav>
          )}
        </header>
      </Ctx.Provider>
    );
  },
);
AppBar.displayName = "AppBar";

const AppBarBrand = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      className={cn("flex shrink-0 items-center gap-2 text-[15px] font-semibold text-foreground", className)}
      {...props}
    />
  ),
);
AppBarBrand.displayName = "AppBarBrand";

const AppBarNav = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  ({ className, ...props }, ref) => (
    <nav ref={ref} className={cn("hidden items-center gap-1 md:flex", className)} {...props} />
  ),
);
AppBarNav.displayName = "AppBarNav";

export interface AppBarLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Marks the current destination — sets `aria-current="page"` and the active style. */
  active?: boolean;
  /** Render as the child element (e.g. a framework `<Link>`), forwarding props. */
  asChild?: boolean;
}

const AppBarLink = React.forwardRef<HTMLAnchorElement, AppBarLinkProps>(
  ({ className, active, asChild, ...props }, ref) => {
    const Comp = asChild ? Slot : "a";
    return (
      <Comp
        ref={ref}
        data-active={active ? "" : undefined}
        aria-current={active ? "page" : undefined}
        className={cn(
          "inline-flex items-center rounded-md px-3 py-1.5 text-sm font-medium outline-none transition-colors",
          "text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring",
          "data-[active]:bg-accent data-[active]:text-foreground",
          className,
        )}
        {...props}
      />
    );
  },
);
AppBarLink.displayName = "AppBarLink";

const AppBarActions = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("ms-auto flex shrink-0 items-center gap-2", className)} {...props} />
  ),
);
AppBarActions.displayName = "AppBarActions";

export { AppBar, AppBarBrand, AppBarNav, AppBarLink, AppBarActions, useAppBar };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
